def update_meta_weights(X_aug, y, meta_weights, lr, loss_fn):
 pred = X_aug @ meta_weights
 error = pred - y
 grad = loss_fn(error) @ X_aug.T
 new_weights = meta_weights - lr * grad
 return new_weights, np.sqrt(np.mean((pred - y) ** 2))

