def calculate_median(numbers):
 sorted_nums = sorted(numbers)
 mid = len(sorted_nums) // 2
 if len(sorted_nums) % 2 == 0:
 return (sorted_nums[mid - 1] + sorted_nums[mid]) / 2
 else:
 return sorted_nums[mid]

def compute_gini(branch_class_counts):
 # Gini = 1 - sum(p_c^2) where p_c = count_c / n
 n = sum(branch_class_counts)
 if n == 0:
 return 0.0
 total_gini = 0.0
 for count in branch_class_counts:
 p = count / n
 total_gini += p ** 2
 return 1.0 - total_gini

def find_omitted(original_data, bootstrap_sample):
 original_set = set(original_data)
 sample_set = set(bootstrap_sample)
 return sorted(list(original_set - sample_set))
